import{_ as a,a as e}from"./chunks/08-model-settings.wwAq27Vh.js";import{_ as r}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as o,o as i,c as n,a2 as l}from"./chunks/framework.z3u3TMv0.js";const f=JSON.parse('{"title":"모델 연결과 파라미터","description":"MiniTavern BYOK 모델 연결 — Base URL·API Key 입력, 테스트, 샘플링; 클라우드 또는 Ollama/LM Studio 로컬 OpenAI 호환.","frontmatter":{"title":"모델 연결과 파라미터","description":"MiniTavern BYOK 모델 연결 — Base URL·API Key 입력, 테스트, 샘플링; 클라우드 또는 Ollama/LM Studio 로컬 OpenAI 호환.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"모델 연결과 파라미터 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK 모델 연결 — Base URL·API Key 입력, 테스트, 샘플링; 클라우드 또는 Ollama/LM Studio 로컬 OpenAI 호환."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/manual/model-link"}]]},"headers":[],"relativePath":"ko/manual/model-link.md","filePath":"ko/manual/model-link.md","lastUpdated":1787224147000}'),d={name:"ko/manual/model-link.md"};function s(p,t,h,u,c,m){return i(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="모델-연결과-파라미터" tabindex="-1">모델 연결과 파라미터 <a class="header-anchor" href="#모델-연결과-파라미터" aria-label="Permalink to &quot;모델 연결과 파라미터&quot;">​</a></h1><p>BYOK: 키는 기기 보안 저장소에; 요청은 설정한 주소로 직결됩니다.</p><p>유료 API가 없으면 <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>; PC 배포는 <a href="/ultra_guides/ko/local/">로컬 모델</a>.</p><h2 id="모델-연결" tabindex="-1">모델 연결 <a class="header-anchor" href="#모델-연결" aria-label="Permalink to &quot;모델 연결&quot;">​</a></h2><p>경로: <strong>설정 → 모델 → 모델 연결</strong></p><p><img src="'+a+'" alt="모델 연결 목록"></p><table tabindex="0"><thead><tr><th>조작</th><th>설명</th></tr></thead><tbody><tr><td>새로 만들기</td><td>플랫폼, 키, Base URL, 모델</td></tr><tr><td>편집 / 복사 / 삭제</td><td>목록 오른쪽 메뉴</td></tr><tr><td>기본값으로 설정</td><td>새 대화의 기본</td></tr><tr><td>테스트</td><td>저장 전 또는 편집 페이지 「테스트」. <strong>텍스트 채팅</strong> 모델이어야 함; TTS / 이미지 전용 ID（예 Gemini <code>*-tts</code>）는 텍스트 대화 미지원 → <a href="./errors#textoutputunsupported">오류 · textOutputUnsupported</a></td></tr></tbody></table><h3 id="플랫폼-유형-자주-씀" tabindex="-1">플랫폼 유형（자주 씀） <a class="header-anchor" href="#플랫폼-유형-자주-씀" aria-label="Permalink to &quot;플랫폼 유형（자주 씀）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>옵션（문서는 App 기준）</th><th>용도</th></tr></thead><tbody><tr><td>각 클라우드 프리셋</td><td>국내/국제 Base URL 자동</td></tr><tr><td>Custom (OpenAI)</td><td>로컬 Ollama / LM Studio, 호환 게이트웨이</td></tr><tr><td>Custom Gemini / Anthropic</td><td>해당 프로토콜 엔드포인트</td></tr></tbody></table><p>다중 사이트 플랫폼은 「국제 사이트 사용」전환 가능. 로컬: <a href="/ultra_guides/ko/connect-app/minitavern">MiniTavern 연결</a> · <a href="/ultra_guides/ko/local/tools">도구 개요</a>.</p><p><img src="'+r+'" alt="연결 만들기"></p><h2 id="모델-설정-전역-파라미터" tabindex="-1">모델 설정（전역 파라미터） <a class="header-anchor" href="#모델-설정-전역-파라미터" aria-label="Permalink to &quot;모델 설정（전역 파라미터）&quot;">​</a></h2><p>경로: <strong>설정 → 모델 설정</strong></p><p><img src="'+e+'" alt="모델 설정"></p><p>자주 쓰는 항목（이름은 App 기준）:</p><ul><li>기억 길이（히스토리 수）</li><li>응답 토큰（max tokens, 상한 128000; 일부 Claude 장면에서는 <strong>None 금지</strong>）</li><li>Temperature, Top-P / Top-K</li><li>스트리밍 여부</li></ul><h2 id="세션별-덮어쓰기" tabindex="-1">세션별 덮어쓰기 <a class="header-anchor" href="#세션별-덮어쓰기" aria-label="Permalink to &quot;세션별 덮어쓰기&quot;">​</a></h2><p>경로: 대화 → <strong>설정</strong> → 모델 연결 / 파라미터</p><p>한 채팅만 연결·샘플링을 바꿀 수 있으며 전역 기본값은 유지됩니다.</p><h2 id="채팅-설정의-이미지-인식" tabindex="-1">채팅 설정의 이미지 인식 <a class="header-anchor" href="#채팅-설정의-이미지-인식" aria-label="Permalink to &quot;채팅 설정의 이미지 인식&quot;">​</a></h2><p>경로: <strong>설정 → 채팅 → 이미지 인식 설정</strong></p><p>단톡은 채팅 설정 → <strong>이미지 인식과 표시</strong>에서 기본을 따르거나 단독 덮어쓰기（묘사 모델·프롬프트는 전역）.</p><ul><li>「이미지 묘사」끄기: 멀티모달로 그림을 모델에 직접 전달（비전 지원 필요）.</li><li>켜기: 현재 채팅 주 모델이 <strong>이미지 파라미터를 지원하지 않을 때만</strong> — 묘사 모델이 먼저 그림을 텍스트로（인물 인식과 같은 요청 가능）, 그다음 주 모델; 묘사 결과는 캐시 재사용. 주 모델이 비전을 지원하면 여전히 멀티모달 직전, 이 스위치는 막지 않음.</li></ul><p>이미지 미지원 주 모델 + 묘사 켠 뒤 순서: 묘사（+인물）→ 주 채팅（스마트/키워드 이미지 응답이 있으면 이미지 프롬프트 첨부）→ 응답에 이미지 데이터가 있으면 바이패스 생성.</p><p>「현재 모델이 이미지를 지원하지 않음」→ <a href="./errors#visionunsupported">오류 · visionUnsupported</a>.</p><h2 id="이미지-생성-연결-응답-이미지-키워드" tabindex="-1">이미지 생성（연결 / 응답 이미지 / 키워드） <a class="header-anchor" href="#이미지-생성-연결-응답-이미지-키워드" aria-label="Permalink to &quot;이미지 생성（연결 / 응답 이미지 / 키워드）&quot;">​</a></h2><p>경로: <strong>설정 → 이미지 생성</strong></p><ul><li><strong>이미지 연결 / 이미지 설정</strong>: API, 크기/품질, 생성 수（<code>/imagine</code>만）, 강화/네거티브 프롬프트（<code>/imagine</code>과 첨부 메뉴 생성만; 기본 화질 단어 / 저품질·흐림·여분 손가락·워터마크 등）</li><li><strong>응답 이미지</strong>（이미지 설정 안）: 먼저 스위치, 그다음 트리거 방식. 끄면 채팅이 자동 출도하지 않음（슬래시, 첨부 메뉴, 말풍선 길게 누르기는 영향 없음） <ul><li><strong>스마트 판단</strong>: 모델이 이 라운드에 이미지를 낼지 판단; 구도는 장면별（폰 셀카 3:4, 카메라 3:2）, 히트 시 1장. 첨부 가능（예 「이런 스타일로」）— 스타일 참고이며 캐릭터/유저 신원 판정을 대체하지 않음</li><li><strong>키워드 트리거</strong>: 사용자 메시지가 키워드 규칙에 맞으면 출도（첨부 가능）; 화면·구도는 현재 대화 기준, 히트 시 1장</li></ul></li><li><strong>키워드 트리거 이미지</strong>: 규칙 설정. 실제로 쓰려면 이미지 설정에서 응답 이미지를 켜고 키워드 트리거를 선택</li></ul><p>채팅에서 이미지 생성:</p><table tabindex="0"><thead><tr><th>입구</th><th>설명</th></tr></thead><tbody><tr><td><code>/imagine 프롬프트</code></td><td>주 채팅 모델이 대화 관련 여부·캐릭터/유저 참고 필요 여부를 판단한 뒤 프롬프트를 만들어 생성. 첨부는 참고용이며 말로는 나가지 않음. 장수는 이미지 설정의 「생성 수」. 실패 시 버블이 남고 재시도</td></tr><tr><td><code>/imagine scene</code> / 첨부 → 스토리 기준</td><td>최근 대화로 현재 장면, 1장</td></tr><tr><td><code>/imagine last</code> / 첨부 → 마지막 메시지</td><td>마지막 메시지 기준, 1장</td></tr><tr><td>첨부 → 배경 생성</td><td>환경 배경 1장; 완료 후 채팅 배경으로 설정 가능</td></tr><tr><td>말풍선 길게 누르기 → 이미지</td><td>해당 버블 기준, 1장</td></tr></tbody></table><p>이미지 연결이 없으면 첨부 메뉴 네 가지 모드와 <code>/imagine</code> 전송 시 「설정으로 / 취소」팝업（입력란은 비우지 않음）. 스마트/키워드 자동 출도는 Toast. 응답 이미지를 켤 때 연결이 없으면 팝업하고 스위치는 꺼진 채.</p><p>예: 「셀카 한 장」은 캐릭터 참고+대화 맥락; 「강아지 사진」은 독립 요청으로 캐릭터 얼굴을 씌우지 않음.</p><p>로컬 A1111 / ComfyUI: <a href="/ultra_guides/ko/local/image-gen/">이미지 모델 배포</a> · <a href="/ultra_guides/ko/local/image-gen/connect-app">App 연결</a>.<br> 클라우드 무료: <a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 클라우드 · 이미지</a>.</p><h2 id="오류-입구" tabindex="-1">오류 입구 <a class="header-anchor" href="#오류-입구" aria-label="Permalink to &quot;오류 입구&quot;">​</a></h2><p>테스트·채팅 실패 → Toast / 버블 → <strong>상세 보기</strong>（오류 코드 + 원인 + 제안）→ <a href="./errors">오류 코드</a>.</p>',35)])])}const k=o(d,[["render",s]]);export{f as __pageData,k as default};
